const raw = $json.body ?? $json;
const parsed = typeof raw === 'string' ? JSON.parse(raw) : raw;
const b = parsed?.data ?? parsed?.input ?? parsed ?? {};
const value = (keys) => keys.map((key) => b[key]).find((item) => item !== undefined && item !== null && item !== '');
const normalized = { product: value(['product', 'product_name', 'productName', 'product_query', 'productQuery']), origin_country: value(['origin_country', 'originCountry', 'origin']), destination_country: value(['destination_country', 'destinationCountry', 'destination', 'dest']), quantity_kg: value(['quantity_kg', 'quantityKg', 'quantity']), target_price_usd: value(['target_price_usd', 'targetPriceUSD', 'target_price', 'price_usd']), trade_value_usd: value(['trade_value_usd', 'tradeValueUSD', 'trade_value']), trade_flow: value(['trade_flow', 'tradeFlow']), regime: value(['regime', 'strategy']), certifications: value(['certifications', 'required_certifications']) };
if (normalized.target_price_usd === undefined && normalized.trade_value_usd !== undefined && Number(normalized.quantity_kg) > 0) normalized.target_price_usd = Number(normalized.trade_value_usd) / Number(normalized.quantity_kg);
const required = ['product', 'origin_country', 'destination_country', 'quantity_kg', 'target_price_usd'];
const missing = required.filter((k) => normalized[k] === undefined || normalized[k] === null || normalized[k] === '');
if (missing.length) throw new Error(`Missing required fields: ${missing.join(', ')}. Send product, origin_country, destination_country, quantity_kg, and target_price_usd.`);
const quantity = Number(normalized.quantity_kg);
const price = Number(normalized.target_price_usd);
if (!Number.isFinite(quantity) || quantity <= 0 || !Number.isFinite(price) || price <= 0) throw new Error('quantity_kg and target_price_usd must be positive numbers');
return [{ json: { product: String(normalized.product), origin_country: String(normalized.origin_country).toUpperCase(), destination_country: String(normalized.destination_country).toUpperCase(), quantity_kg: quantity, target_price_usd: price, trade_flow: normalized.trade_flow || 'Export', regime: normalized.regime || 'balanced', certifications: Array.isArray(normalized.certifications) ? normalized.certifications : [] } }];

const results = { hs_classification: $('ML - HS Classification').item.json, market_opportunity: $('ML - Market Opportunity XGBoost').item.json, trade_risk: $('ML - Trade Risk Anomaly').item.json, compliance: $('ML - Compliance RAG').item.json, country_matches: $('ML - Country Counterparty Matching').item.json, executive_dossier: $('ML - Executive Trade Dossier').item.json };
const stepStatus = {};
let failedCount = 0;
for (const [key, val] of Object.entries(results)) {
  const failed = !!(val && val.error);
  stepStatus[key] = failed ? 'FAILED' : 'OK';
  if (failed) failedCount++;
}
const totalSteps = Object.keys(results).length;
const overallStatus = failedCount === 0 ? 'SUCCESS' : (failedCount === totalSteps ? 'FAILED' : 'PARTIAL');
return [{ json: { status: overallStatus, step_status: stepStatus, input: $('Validate Analyze Input').item.json, ...results, provenance: ['Express /predict/hs-code', 'Express /predict/market-opportunity', 'Express /api/trade-anomaly/predict', 'Express /compliance/rag-analyze', 'Express /predict/counterparty-match', 'Express /api/v1/trade/generate-report'], executed_at: new Date().toISOString() } }];

